def roman_to_int(s):
    values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    for pair, spelled in (("IV", "IIII"), ("IX", "VIIII"), ("XL", "XXXX"), ("XC", "LXXXX"), ("CD", "CCCC"), ("CM", "DCCCC")):
        s = s.replace(pair, spelled)
    total = 0
    for ch in s:
        total += values[ch]
    return total

print(roman_to_int(s))

